using System.Linq; using System.Web.Mvc; using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Controllers { public class AccountController:Controller { private StoreContext db=new StoreContext(); public ActionResult Login(){return View();} [HttpPost,ValidateAntiForgeryToken] public ActionResult Login(string username,string password){var u=db.Users.FirstOrDefault(x=>x.Username==username&&x.Password==password);if(u==null){ViewBag.Error="Tên đăng nhập hoặc mật khẩu không đúng.";return View();}Session["Username"]=u.Username;Session["Role"]=u.UserRole;return RedirectToAction("Index","Home");} public ActionResult Register(){return View();} [HttpPost,ValidateAntiForgeryToken] public ActionResult Register(string username,string password,string name,string phone,string email,string address){if(string.IsNullOrWhiteSpace(username)||string.IsNullOrWhiteSpace(password)||string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(phone)){ViewBag.Error="Vui lòng nhập đủ thông tin bắt buộc.";return View();}if(db.Users.Any(x=>x.Username==username)){ViewBag.Error="Tên đăng nhập đã tồn tại.";return View();}db.Users.Add(new StoreUser{Username=username,Password=password,UserRole="C"});db.SaveChanges();db.Customers.Add(new Customer{Username=username,CustomerName=name,CustomerPhone=phone,CustomerEmail=email,CustomerAddress=address});db.SaveChanges();return RedirectToAction("Login");} public ActionResult Logout(){Session.Clear();return RedirectToAction("Index","Home");} public ActionResult MyProfile(){if(Session["Username"]==null)return RedirectToAction("Login");var c=db.Customers.FirstOrDefault(x=>x.Username.ToString()==Session["Username"].ToString());return View(c);} protected override void Dispose(bool disposing){if(disposing)db.Dispose();base.Dispose(disposing);} } }